            self.is_in(*local),
        ensures
            MemContents::Init(*segment) == local.thread_token.value().segments.index(self.segment_id@).shared_access.points_to.opt_value(),
    {
        let tracked perm =
            &local.instance.thread_local_state_guards_segment(
